Definition ecclear_postZ (ra : word) (SP : Z) (gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (E lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra (Z_to_bv 64 SP) gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom asegs)
    /\ munch [(lo, SP); (E, E + 24)]%Z m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ stk asegs m' lo SP
    /\ rw_cells asegs m' E (ErrCodeCells EC_clear)
    /\ ACONST m'.

Lemma ecclearZ : forall pc, ecclear_stmt pc ->
  forall ra (SP : Z) gp tp t0 t1 t2 s0 s1 a0 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (E lo : Z) (ej : list byte),
  rw_cells asegs m E [CB 24 ej] ->
  stk asegs m lo SP -> lo + ECCLEAR_STACK <= SP -> aceil <= lo -> SP < 2^64 ->
  aapp E 24 -> mem_inv asegs m -> ACONST m -> accessible m E 24 -> shvis m E (E + 24) ->
  evt asegs (ecclear_postZ ra SP gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc E lo m)
    (MS (mkR ra (Z_to_bv 64 SP) gp tp t0 t1 t2 s0 s1 a0 (wz E) a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 pc) fc None m (seg_rom asegs)).
Proof.
  intros pc EC. intros until ej. intros C ST LO CEIL SPH APE MI AC ACE SV.
  unfold ECCLEAR_STACK, ACL_STACK, OBINIT_STACK, AINTRIN_STACK in *. assert (SP0 : 0 <= SP) by (destruct ST as [? _]; lia).
  eapply evt_mono.
  { eapply (EC ra (Z_to_bv 64 SP)); rewrite ?unsigned_lit by lia; try eassumption. }
  intros ms' PO. cbv beta in PO. unfold ecclear_post in PO. unfold ecclear_postZ.
  rewrite !(unsigned_lit SP) in PO by lia.
  destruct PO as (x0 & x1 & x2 & y0 & y1 & y2 & y3 & y4 & y5 & y6 & y7 & x3 & x4 & x5 & x6 & m' & -> & MU & WM & MI' & ST' & C' & AC').
  do 16 eexists. split; [reflexivity|]. repeat (split; [eassumption|]). exact AC'.
Qed.

Definition cl_postZ (ra : word) (SP : Z) (gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (P R lo : Z) (c : pcore) (pad7 pad2 rj : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra (Z_to_bv 64 SP) gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom asegs)
    /\ munch [(lo, SP); (R, R + 16)]%Z m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ stk asegs m' lo SP
    /\ rw_cells asegs m' P (ParserCoreCells c pad7 pad2)
    /\ rw_cells asegs m' R (cl_cells c rj)
    /\ ACONST m'.
Scheme kc__1 := Elimination for Corelib.Init.Logic.and Sort Prop.
Scheme kc__2 := Elimination for Corelib.Init.Logic.ex Sort Prop.

Lemma clZ : cl_stmt ->
  forall ra (SP : Z) gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (P R lo : Z) (c : pcore) (pad7 pad2 rj : list byte),
  rw_cells asegs m P (ParserCoreCells c pad7 pad2) -> pcore_ok c -> 3 <= pc_state c ->
  rw_cells asegs m R [CB 16 rj] -> (P + 80 <= R \/ R + 16 <= P) ->
  stk asegs m lo SP -> lo + ACL_STACK <= SP -> aceil <= lo -> SP < 2^64 ->
  (P + 80 <= lo \/ SP <= P) -> (R + 16 <= lo \/ SP <= R) ->
  mem_inv asegs m ->
  ACONST m -> accessible m P 80 -> P mod 8 = 0 -> accessible m R 16 -> R mod 8 = 0 -> awin (R, R + 16) ->
  evt asegs (cl_postZ ra SP gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc P R lo c pad7 pad2 rj m)
    (MS (mkR ra (Z_to_bv 64 SP) gp tp t0 t1 t2 s0 s1 (wz R) (wz P) a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_A_BP_CONTENT_LENGTH) fc None m (seg_rom asegs)).
