Definition obinit_postZ (ra : word) (SP : Z) (gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (P E lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra (Z_to_bv 64 SP) gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom asegs)
    /\ munch [(lo, SP); (E, E + 24); (P + 240, P + 241)]%Z m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ stk asegs m' lo SP
    /\ rw_cells asegs m' E (ErrCodeCells EC_clear)
    /\ rw_cells asegs m' (P + 240) [C1 (b8 1)]
    /\ ACONST m'.

Lemma obinitZ : obinit_stmt ->
  forall ra (SP : Z) gp tp t0 t1 t2 s0 s1 a1 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (P E lo : Z) (rdi : byte) (ej : list byte),
  rw_cells asegs m (P + 240) [C1 rdi] ->
  rw_cells asegs m E [CB 24 ej] ->
  (P + 241 <= E \/ E + 24 <= P + 240) ->
  stk asegs m lo SP -> lo + OBINIT_STACK <= SP -> aceil <= lo -> SP < 2^64 ->
